parameters.text:
=Extract all factual claims from this text that can be independently verified.

Text: {{ $json.text_to_check }}
Domain: {{ $json.domain }}

Only extract claims that are:
- Specific and verifiable (not opinions)
- Factual assertions (statistics, dates, names, events, scientific claims)
- Checkable against external sources

Return JSON:
{
  "claims": [
    {"claim": "exact claim text", "claim_type": "statistic/date/name/event/scientific", "checkable": true}
  ],
  "total_claims": 0,
  "uncheckable_statements": ["opinions or subjective statements"]
}

parameters.jsCode:
const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const data = JSON.parse(raw);
return data.claims.filter(c => c.checkable).map(c => ({ json: { ...c, original_text: $('Set Check Config').item.json.text_to_check, domain: $('Set Check Config').item.json.domain } }));

parameters.jsonBody:
={
  "model": "sonar",
  "messages": [{"role": "user", "content": "Fact check this specific claim. Search current sources and determine if it is TRUE, FALSE, or PARTIALLY TRUE. Provide a brief explanation and cite your source.\n\nClaim: {{ $json.claim }}"}],
  "search_recency_filter": "year"
}

parameters.jsCode:
const response = $input.item.json.choices[0].message.content;
const verdict = response.toLowerCase().includes('false') ? 'FALSE' : response.toLowerCase().includes('partially') ? 'PARTIALLY TRUE' : 'TRUE';
return [{ json: { claim: $('Parse Claims').item.json.claim, verdict, explanation: response.substring(0, 300), claim_type: $('Parse Claims').item.json.claim_type } }];
